import{z as l,x as s,o as A,c as D,q as t,j as r,D as a,d as e,s as B,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"AEAD 的深入","description":"","frontmatter":{"title":"AEAD 的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-aead-deep.md","filePath":"cs/ce-aead-deep.md","lastUpdated":1791063341000}'),c={name:"cs/ce-aead-deep.md"};function d(C,E,p,S,m,F){const o=s("Mermaid");return A(),D("div",null,[E[2]||(E[2]=t('<h1 id="aead-的深入" tabindex="-1">AEAD 的深入 <a class="header-anchor" href="#aead-的深入" aria-label="Permalink to &quot;AEAD 的深入&quot;">​</a></h1><div class="epigraph"><p>AEAD 的函数签名只有一行；合同的全部重量都压在 nonce 的来源上——误用发生之后，标签照样验证通过，坏消息也照样递送。</p><footer>—— 据 RFC 5116；Rogaway and Shrimpton, 2006；NIST SP 800-38D 整理</footer></div><p><a href="/cs/ce-symmetric-modes">上一课</a>把模式选择钉成清单：默认 AEAD，nonce 计数器分配或长随机。本课打开这一行签名本身：明文、AAD、nonce、标签四个参数各管什么，nonce 违约后失败以什么形状出现，以及在 nonce 来源不可信的场合（存储加密、多写者覆盖、乱序交付）该换哪套合同——误用抵抗的 SIV 一族。后课的 KEM 组合与协议陷阱，都默认你能分清「nonce 错了」与「协议错了」这两种失败。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RFC 5116 把 AEAD 收成 encrypt(key, nonce, plaintext, aad) → ciphertext, tag。AAD 不加密但进标签：头部、版本号、序列号要被认证却要保持可读。这份合同默认 nonce 唯一，却没有机制强制。GCM 在 nonce 复用后的失败是复合的：CTR 层泄露两条明文的异或；GHASH 层更糟，认证子是认证子密钥 \\(H\\) 的多项式求值，同 nonce 的两条消息即可恢复 \\(H\\)，此后攻击者能对任意新消息伪造标签（Procter 2014 的 forbidden attack）。缺口是两问：失败模型决定选型——「nonce 绝对可控」才配用 GCM 一族；不可控时，用把 nonce 也吃进计算的 SIV。</p><p><span class="marginnote">术语翻译：AAD（附加认证数据）就是用「不加密但参与认证」的手段来做「保护元数据」的事——包头、版本号要可读（中间设备要看），但谁改了它，标签验证就必须失败。</span></p><h3 id="siv-合成-iv" tabindex="-1">SIV：合成 IV <a class="header-anchor" href="#siv-合成-iv" aria-label="Permalink to &quot;SIV：合成 IV&quot;">​</a></h3><p>SIV（Rogaway and Shrimpton 2006 的确定性 AEAD；AES-GCM-SIV 见 RFC 8452）把方向倒过来：先从密钥、明文与 AAD 算合成 IV，\\(S = \\mathrm{PRF}(k_1, \\mathrm{AAD} \\| \\mathrm{plaintext})\\)，再用 \\(k_2\\) 与 \\(S\\) 做 CTR 加密。nonce 复用不再灾难：相同输入得到相同密文（确定性加密本来如此），不同输入的碰撞概率被 PRF 压回生日界。代价是不再 online：加密前要缓冲整个明文，流式大消息不友好。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型三问。一问 nonce 来源：由本端单调计数器产生、且重放由序列号拒绝——GCM 或 ChaCha20-Poly1305；由不可信方提供（存储块的地址重映射、多写者覆盖、UDP 乱序重传）——SIV 一族。二问消息上限：GCM 单密钥总账受 SP 800-38D 的 \\(2^{39}-256\\) 比特界；流式协议把大消息切成记录、每记录新 nonce，上限随记录数下降，TLS 的 \\(2^{14}\\) 字节记录上限正是在这套账里。三问失败语义：标签验证失败必须整体丢弃，不能把「解密为什么失败」区分给调用方——那是「协议实现的陷阱」课里预言机的入口。另记一笔：重放拒绝不是 AEAD 的职责，标签验证通过不等于消息是新的，序列号与去重表要外做，TLS 的记录序号正是补在 AEAD 外面的这段账。</p><p><span class="marginnote">数字实例：随机取 96 位 nonce，发到约 \\(2^{32}\\) 条消息时复用概率就到 \\(2^{-32}\\) 量级——所以 TLS 不掷骰子，直接用「静态方向位 + 64 位记录序号」当 nonce，唯一性靠序号单调保证，不靠运气。</span></p>',11)),(A(),r(i,null,{default:a(()=>[B(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E4%B8%8E%20AAD%22%5D%20--%3E%20Q%7B%22nonce%20%E6%9D%A5%E6%BA%90%E5%8F%AF%E4%BF%A1%3F%22%7D%0A%20%20Q%20--%3E%7C%E8%AE%A1%E6%95%B0%E5%99%A8%E6%88%96%E9%95%BF%E9%9A%8F%E6%9C%BA%7C%20GCM%5B%22GCM%20%2F%20ChaCha20-Poly1305%22%5D%0A%20%20GCM%20--%3E%20TAG%5B%22tag%2016%20%E5%AD%97%E8%8A%82%EF%BC%8C%E9%AA%8C%E8%AF%81%E5%A4%B1%E8%B4%A5%E6%95%B4%E4%BD%93%E4%B8%A2%E5%BC%83%22%5D%0A%20%20Q%20--%3E%7C%E4%B8%8D%E5%8F%AF%E4%BF%A1%E6%88%96%E4%BC%9A%E5%A4%8D%E7%94%A8%7C%20SIV%5B%22SIV%EF%BC%9A%E5%85%88%E5%90%88%E6%88%90%20IV%20%E5%86%8D%20CTR%22%5D%0A%20%20SIV%20--%3E%20DET%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%EF%BC%9A%E7%9B%B8%E5%90%8C%E8%BE%93%E5%85%A5%E7%9B%B8%E5%90%8C%E5%AF%86%E6%96%87%22%5D%0A%20%20TAG%20--%3E%20RP%5B%22%E9%87%8D%E6%94%BE%E5%8F%A6%E5%81%9A%EF%BC%9A%E5%BA%8F%E5%88%97%E5%8F%B7%E5%8E%BB%E9%87%8D%22%5D%0A%20%20DET%20--%3E%20RP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"两族的安全目标不同。GCM 族证明的是 nonce-based AE 安全：同一 nonce 只允许一条消息，优势随消息总量的生日项上涨。SIV 证明的是误用抵抗：攻击者可以诱导 nonce 重复，拿到的只是「明文相等」这一个事实。写成机制：GCM 复用后泄露 \\(P_1 \\oplus P_2\\) 与认证子密钥 \\(H\\)，随后可主动伪造；SIV 复用后泄露的只有 \\(P_1 = P_2\\)。工程含义落在场景上：存储加密的同一扇区反复覆写、内容寻址日志的去重，用 GCM 的失败是主动伪造，用 SIV 的失败只是泄露相等性——两者相差一整个威胁模型。还有一个常被漏掉的合同是密钥承诺（key commitment）：GCM 的密文在多个不同密钥下可能都验证通过，多密钥系统里密文会「认错主人」；标准库默认无此性质，需要它的场合要选带承诺的修补构造，不能假设。",-1)),(A(),r(i,null,{default:a(()=>[B(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20DUP%5B%22%E5%90%8C%E4%B8%80%20nonce%20%E5%8A%A0%E5%AF%86%E4%B8%A4%E6%9D%A1%E6%B6%88%E6%81%AF%22%5D%20--%3E%20GB%5B%22GCM%EF%BC%9A%E5%A4%8D%E5%90%88%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20DUP%20--%3E%20SB%5B%22SIV%EF%BC%9A%E6%9C%89%E9%99%90%E6%B3%84%E9%9C%B2%22%5D%0A%20%20GB%20--%3E%20X%5B%22%E6%B3%84%E9%9C%B2%E4%B8%A4%E6%98%8E%E6%96%87%E7%9A%84%E5%BC%82%E6%88%96%22%5D%0A%20%20GB%20--%3E%20HH%5B%22%E6%81%A2%E5%A4%8D%E8%AE%A4%E8%AF%81%E5%AD%90%E5%AF%86%E9%92%A5%20H%22%5D%0A%20%20HH%20--%3E%20FORGE%5B%22%E5%8F%AF%E5%AF%B9%E4%BB%BB%E6%84%8F%E6%96%B0%E6%B6%88%E6%81%AF%E4%BC%AA%E9%80%A0%E6%A0%87%E7%AD%BE%22%5D%0A%20%20SB%20--%3E%20EQ%5B%22%E5%8F%AA%E6%B3%84%E9%9C%B2%E4%B8%A4%E6%9D%A1%E6%98%8E%E6%96%87%E7%9B%B8%E7%AD%89%22%5D%0A%20%20FORGE%20--%3E%20CON%5B%22%E5%A8%81%E8%83%81%E5%8D%87%E7%BA%A7%EF%BC%9A%E4%B8%BB%E5%8A%A8%E4%BC%AA%E9%80%A0%E5%8F%AF%E8%A1%8C%22%5D%0A%20%20EQ%20--%3E%20CON2%5B%22%E6%AD%A2%E6%AD%A5%E4%BA%8E%E8%A7%82%E5%AF%9F%E7%9B%B8%E7%AD%89%E6%80%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者容易以为「标签验证通过 = 消息可信且新鲜」，实际上标签只证明「密文没被改、出自持密钥者」——重放的旧消息标签照样通过；新鲜性要靠 AEAD 外面的序列号与去重窗口。</span></p><p><span class="marginnote">RFC 8452 的 AES-GCM-SIV 在每次调用里额外算一遍合成 IV：nonce 乱来不死人，代价是每消息多一遍全量计算。TLS 1.3 没有采用它——协议层的序号管理已经把 nonce 唯一性钉死，这是「合同分摊」而不是「单层加强」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 GHASH 的域运算，那在 <a href="/cs/aead-gcm-internals">AEAD 与 GCM 内部</a>已完成；重放窗口与前向保密是协议层概念，不算进 AEAD。XTS 不是 AEAD，SIV 与它解决的也不是同一个问题：前者防 nonce 误用并给完整性，后者给扇区定长可调加密、无标签。记录边界泄露长度、密钥轮换的调度属于「协议实现的陷阱」；密钥从哪来属于「随机数」课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AEAD 四参合同：明文加密，AAD 只认证，nonce 唯一，标签失败整体丢弃。</li><li>GCM 的 nonce 复用复合失败：异或泄露加认证子密钥恢复，随后任意伪造。</li><li>SIV 先合成 IV 再加密，把复用降级为「泄露相等性」；代价是不再 online。</li><li>重放拒绝与密钥承诺都不在标准 AEAD 里，要外做或选修补构造。</li><li>出处：RFC 5116；Rogaway and Shrimpton, 2006；RFC 8452；NIST SP 800-38D；Procter 2014。</li></ul>',6))])}const P=l(c,[["render",d]]);export{_ as __pageData,P as default};
